import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(
    const float* linear_out,
    const float* bn_scale,
    const float* bn_shift,
    float bias,
    float div_val,
    float* output,
    int total_elements,
    int out_features
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int feat_idx = idx % out_features;
        float val = linear_out[idx] * bn_scale[feat_idx] + bn_shift[feat_idx];
        val += bias;
        val /= div_val;
        val *= 1.0f / (1.0f + expf(-val));
        output[idx] = val;
    }
}

torch::Tensor fused_operation_cuda(
    torch::Tensor linear_out,
    torch::Tensor bn_scale,
    torch::Tensor bn_shift,
    torch::Tensor bias,
    float div_val
) {
    int batch_size = linear_out.size(0);
    int out_features = linear_out.size(1);
    int total_elements = batch_size * out_features;
    auto output = torch::empty_like(linear_out);

    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    fused_op_kernel<<<grid_size, block_size>>>(
        linear_out.data_ptr<float>(),
        bn_scale.data_ptr<float>(),
        bn_shift.data_ptr<float>(),
        bias.item<float>(),
        div_val,
        output.data_ptr<float>(),
        total_elements,
        out_features
    );

    return output;
}
"""

cpp_code = "torch::Tensor fused_operation_cuda(torch::Tensor linear_out, torch::Tensor bn_scale, torch::Tensor bn_shift, torch::Tensor bias, float div_val);"

fused_op_ext = load_inline(
    name='fused_op_ext',
    cpp_sources=cpp_code,
    cuda_sources=fused_kernel_code,
    functions=['fused_operation_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, bn_eps=1e-5, bn_momentum=0.1, bias_shape=(1,), divide_value=1.0):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.bn = nn.BatchNorm1d(out_features, eps=bn_eps, momentum=bn_momentum)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.divide_value = divide_value

        # Initialize buffers for fused params
        self.register_buffer('bn_scale', torch.empty(out_features))
        self.register_buffer('bn_shift', torch.empty(out_features))

    def forward(self, x):
        x = self.matmul(x)

        # Precompute BN affine parameters
        bn_scale = self.bn.weight / torch.sqrt(self.bn.running_var + self.bn.eps)
        bn_shift = self.bn.bias - self.bn.weight * self.bn.running_mean / torch.sqrt(self.bn.running_var + self.bn.eps)

        # Execute fused kernel
        x = fused_op_ext.fused_operation_cuda(
            x,
            bn_scale,
            bn_shift,
            self.bias,
            self.divide_value
        )
        return x
